    #[allow(clippy::too_many_arguments)]
    fn place_fatality_filter_copy(
        game: &mut Game,
        identities: &mut BTreeMap<&'static str, IdentityHash>,
        name: &'static str,
        card: &str,
        controller: Seat,
        region: Region,
        stealthed: bool,
        warded: bool,
        damage: u16,
        location: Cell,
    ) {
        let instance_id = identity_hash(&json!({ "fixture": name, "kind": "fatality-filter" }))
            .expect("fixture identity");
        let mut unit = test_minion(
            fatality_filter_card_id(game, card),
            instance_id.as_str(),
            controller,
            location,
            None,
        );
        unit.damage = damage;
        unit.region = region;
        unit.stealthed = stealthed;
        unit.tapped = false;
        unit.warded = warded;
        identities.insert(name, instance_id);
        game.position.units.push(unit);
    }

    fn fatality_filter_targets(game: &Game) -> BTreeSet<IdentityHash> {
        game.legal_actions()
            .expect("Fatality actions")
            .into_iter()
            .filter_map(|action| match action.descriptor {
                ActionDescriptor::CastMagic {
                    target: Some(UnitTarget::Minion { instance_id, .. }),
                    ..
                } => Some(instance_id),
                _ => None,
            })
            .collect()
    }

    fn cast_fatality_filter_on(
        game: &mut Game,
        target: &IdentityHash,
    ) -> Vec<(String, serde_json::Value)> {
        let cast = game
            .legal_actions()
            .expect("Fatality actions")
            .into_iter()
            .find(|action| {
                matches!(
                    &action.descriptor,
                    ActionDescriptor::CastMagic {
                        target: Some(UnitTarget::Minion { instance_id, .. }),
                        ..
                    } if *instance_id == *target
                )
            })
            .expect("Fatality target");
        let (events, random_draws) = game.apply_action_recorded(&cast).expect("Fatality cast");
        assert!(random_draws.is_empty());
        events
    }

    fn fatality_filter_alive(game: &Game, id: &IdentityHash) -> bool {
        game.position
            .units
            .iter()
            .any(|unit| unit.card.instance_id == *id)
    }

    fn ensure_fatality_filter_spells(game: &mut Game, count: usize) {
        let card_id = fatality_filter_card_id(game, "north-spell-1");
        let north = &mut game.position.players[seat_index(Seat::North)];
        let mut have = north
            .hand_spellbook
            .iter()
            .filter(|card| card.card_id == card_id)
            .count();
        while have < count {
            have += 1;
            north.hand_spellbook.push(CardInstance {
                realm_entry: 0,
                card_id,
                instance_id: identity_hash(&json!({
                    "fixture": "fatality-filter-spell",
                    "n": have
                }))
                .expect("fatality identity"),
                owner: Seat::North,
                source: CardSource::Spellbook,
            });
        }
    }

    #[expect(
        clippy::too_many_lines,
        reason = "one shared Fatality board keeps Ward, Stealth, underground, healthy, and allied copies together"
    )]
    fn fatality_filter_matrix_board() -> (Game, BTreeMap<&'static str, IdentityHash>) {
        let manifest = selfplay_manifest_with(31, |manifest| {
            for ordinal in 1..=50 {
                manifest["cards"][format!("north-spell-{ordinal}")] = json!({
                    "cardType": "magic",
                    "killTargetWoundedMinion": true,
                    "manaCost": 0,
                    "thresholds": { "air": 0, "earth": 0, "fire": 0, "water": 0 },
                });
            }
            for ordinal in 1..=3 {
                manifest["cards"][format!("south-spell-{ordinal}")]["defense"] = json!(40);
                manifest["cards"][format!("south-spell-{ordinal}")]["manaCost"] = json!(0);
            }
            manifest["cards"]["south-spell-1"]["ward"] = json!(true);
            manifest["cards"]["south-spell-2"]["stealth"] = json!(true);
            manifest["cards"]["south-spell-3"]["burrowing"] = json!(true);
            manifest["cards"]["north-spell-50"] = json!({
                "attack": 1,
                "cardType": "minion",
                "defense": 40,
                "manaCost": 0,
                "stealth": true,
                "thresholds": { "air": 0, "earth": 0, "fire": 0, "water": 0 },
            });
        });
        let mut game = Game::from_manifest_json(&manifest).expect("valid Fatality filter game");
        let c4 = Cell::parse("C4").expect("C4");
        game.position.sites[c4.index()] = Some(SitePosition {
            card: CardInstance {
                realm_entry: 0,
                card_id: fatality_filter_card_id(&game, "north-site-1"),
                instance_id: identity_hash(&json!({ "fixture": "fatality-filter-site" }))
                    .expect("site identity"),
                owner: Seat::North,
                source: CardSource::Atlas,
            },
            controller: Seat::North,
            last_flight_turn: None,
            warded: false,
        });
        game.position.units.clear();
        let mut identities = BTreeMap::new();
        for (name, card, controller, region, stealthed, warded, damage) in [
            (
                "warded",
                "south-spell-1",
                Seat::South,
                Region::Surface,
                false,
                true,
                1,
            ),
            (
                "hidden",
                "south-spell-2",
                Seat::South,
                Region::Surface,
                true,
                false,
                1,
            ),
            (
                "underground",
                "south-spell-3",
                Seat::South,
                Region::Underground,
                false,
                false,
                1,
            ),
            (
                "healthy",
                "south-spell-3",
                Seat::South,
                Region::Surface,
                false,
                false,
                0,
            ),
            (
                "ally",
                "north-spell-50",
                Seat::North,
                Region::Surface,
                true,
                false,
                1,
            ),
        ] {
            place_fatality_filter_copy(
                &mut game,
                &mut identities,
                name,
                card,
                controller,
                region,
                stealthed,
                warded,
                damage,
                c4,
            );
        }
        let north = &mut game.position.players[seat_index(Seat::North)];
        north.avatar.location = c4;
        north.domain_established = true;
        north.mana = 1;
        game.position.active_seat = Seat::North;
        game.position.decision_seat = Seat::North;
        game.position.phase = Phase::Main;
        ensure_fatality_filter_spells(&mut game, 3);
        (game, identities)
    }

    fn assert_fatality_filter_matrix(
        game: &Game,
        identities: &BTreeMap<&'static str, IdentityHash>,
        extra_legal: &[&IdentityHash],
    ) {
        let targets = fatality_filter_targets(game);
        let mut expected = vec![identities["warded"].clone(), identities["ally"].clone()];
        expected.extend(extra_legal.iter().map(|id| (*id).clone()));
        assert_eq!(targets.len(), expected.len());
        assert!(expected.iter().all(|id| targets.contains(id)));
        assert!(!targets.contains(&identities["hidden"]));
        assert!(!targets.contains(&identities["underground"]));
        assert!(!targets.contains(&identities["healthy"]));
    }

    pub fn rule_catalog_0721_fatality_breaks_ward_and_filters_healthy_stealthed_and_underground_copies()
     {
        let (mut game, identities) = fatality_filter_matrix_board();
        assert_fatality_filter_matrix(&game, &identities, &[]);

        let warded_id = identities["warded"].clone();
        let events = cast_fatality_filter_on(&mut game, &warded_id);
        assert_eq!(
            events
                .iter()
                .map(|(event_type, _)| event_type.as_str())
                .collect::<Vec<_>>(),
            ["magic-cast", "ward-broken", "magic-resolved"]
        );
        let surviving = game
            .position
            .units
            .iter()
            .find(|unit| unit.card.instance_id == warded_id)
            .expect("warded target");
        assert_eq!((surviving.damage, surviving.warded), (1, false));
    }

    pub fn rule_catalog_2483_fatality_filter_matrix_persists_after_turns_pass() {
        let (mut game, identities) = fatality_filter_matrix_board();
        assert_fatality_filter_matrix(&game, &identities, &[]);
        game.position.turn_number += 1;
        let warded = game
            .position
            .units
            .iter()
            .find(|unit| unit.card.instance_id == identities["warded"])
            .expect("warded copy");
        assert_eq!(
            (warded.damage, warded.warded, warded.stealthed),
            (1, true, false)
        );
        let hidden = game
            .position
            .units
            .iter()
            .find(|unit| unit.card.instance_id == identities["hidden"])
            .expect("hidden copy");
        assert!(hidden.stealthed);
        assert_eq!(hidden.damage, 1);
        let buried = game
            .position
            .units
            .iter()
            .find(|unit| unit.card.instance_id == identities["underground"])
            .expect("underground copy");
        assert_eq!((buried.region, buried.damage), (Region::Underground, 1));
        let ally = game
            .position
            .units
            .iter()
            .find(|unit| unit.card.instance_id == identities["ally"])
            .expect("allied copy");
        assert_eq!(
            (ally.controller, ally.stealthed, ally.damage),
            (Seat::North, true, 1)
        );
        assert_fatality_filter_matrix(&game, &identities, &[]);
    }

    pub fn rule_catalog_2484_second_fatality_offers_no_targets_after_legal_filter_copies_die() {
        let (mut game, identities) = fatality_filter_matrix_board();
        let ally_id = identities["ally"].clone();
        let warded_id = identities["warded"].clone();
        let events = cast_fatality_filter_on(&mut game, &ally_id);
        assert!(
            events
                .iter()
                .any(|(event_type, _)| event_type == "minion-died")
        );
        assert!(!fatality_filter_alive(&game, &ally_id));
        let ward_events = cast_fatality_filter_on(&mut game, &warded_id);
        assert_eq!(
            ward_events
                .iter()
                .map(|(event_type, _)| event_type.as_str())
                .collect::<Vec<_>>(),
            ["magic-cast", "ward-broken", "magic-resolved"]
        );
        let kill_events = cast_fatality_filter_on(&mut game, &warded_id);
        assert!(
            kill_events
                .iter()
                .any(|(event_type, _)| event_type == "minion-died")
        );
        assert!(!fatality_filter_alive(&game, &warded_id));
        assert!(fatality_filter_alive(&game, &identities["hidden"]));
        assert!(fatality_filter_alive(&game, &identities["underground"]));
        assert!(fatality_filter_alive(&game, &identities["healthy"]));
        assert!(fatality_filter_targets(&game).is_empty());
    }

    pub fn rule_catalog_2485_second_fatality_kills_a_newly_arrived_unfiltered_wounded_minion() {
        let (mut game, mut identities) = fatality_filter_matrix_board();
        let ally_id = identities["ally"].clone();
        let events = cast_fatality_filter_on(&mut game, &ally_id);
        assert!(
            events
                .iter()
                .any(|(event_type, _)| event_type == "minion-died")
        );
        let c4 = Cell::parse("C4").expect("C4");
        place_fatality_filter_copy(
            &mut game,
            &mut identities,
            "visitor",
            "south-spell-3",
            Seat::South,
            Region::Surface,
            false,
            false,
            1,
            c4,
        );
        let visitor_id = identities["visitor"].clone();
        assert!(fatality_filter_targets(&game).contains(&visitor_id));
        assert!(!fatality_filter_targets(&game).contains(&identities["hidden"]));
        let kill = cast_fatality_filter_on(&mut game, &visitor_id);
        assert!(
            kill.iter()
                .any(|(event_type, _)| event_type == "minion-died")
        );
        assert!(!fatality_filter_alive(&game, &visitor_id));
        assert!(fatality_filter_alive(&game, &identities["hidden"]));
        assert!(fatality_filter_alive(&game, &identities["warded"]));
    }

    pub fn rule_catalog_2486_fatality_offers_every_legal_filter_matrix_copy() {
        let (mut game, mut identities) = fatality_filter_matrix_board();
        let c4 = Cell::parse("C4").expect("C4");
        place_fatality_filter_copy(
            &mut game,
            &mut identities,
            "plain",
            "south-spell-3",
            Seat::South,
            Region::Surface,
            false,
            false,
            1,
            c4,
        );
        assert_fatality_filter_matrix(&game, &identities, &[&identities["plain"]]);
    }

    pub fn rule_catalog_2487_fatality_leaves_a_far_stealthed_wounded_copy_untouched() {
        let (mut game, mut identities) = fatality_filter_matrix_board();
        let c1 = Cell::parse("C1").expect("C1");
        game.position.sites[c1.index()] = Some(SitePosition {
            card: CardInstance {
                realm_entry: 0,
                card_id: fatality_filter_card_id(&game, "south-site-1"),
                instance_id: identity_hash(&json!({ "fixture": "fatality-filter-far-site" }))
                    .expect("far site identity"),
                owner: Seat::South,
                source: CardSource::Atlas,
            },
            controller: Seat::South,
            last_flight_turn: None,
            warded: false,
        });
        place_fatality_filter_copy(
            &mut game,
            &mut identities,
            "far_hidden",
            "south-spell-2",
            Seat::South,
            Region::Surface,
            true,
            false,
            1,
            c1,
        );
        let ally_id = identities["ally"].clone();
        let events = cast_fatality_filter_on(&mut game, &ally_id);
        assert!(
            events
                .iter()
                .any(|(event_type, _)| event_type == "minion-died")
        );
        let far = game
            .position
            .units
            .iter()
            .find(|unit| unit.card.instance_id == identities["far_hidden"])
            .expect("far stealthed copy");
        assert_eq!(far.location, c1);
        assert!(far.stealthed);
        assert_eq!(far.damage, 1);
        assert!(!fatality_filter_targets(&game).contains(&identities["far_hidden"]));
    }

    pub fn rule_catalog_2488_second_fatality_kills_a_newly_summoned_unfiltered_wounded_minion() {
        let (mut game, mut identities) = fatality_filter_matrix_board();
        let ally_id = identities["ally"].clone();
        let events = cast_fatality_filter_on(&mut game, &ally_id);
        assert!(
            events
                .iter()
                .any(|(event_type, _)| event_type == "minion-died")
        );
        let c4 = Cell::parse("C4").expect("C4");
        place_fatality_filter_copy(
            &mut game,
            &mut identities,
            "recruit",
            "south-spell-3",
            Seat::South,
            Region::Surface,
            false,
            false,
            1,
            c4,
        );
        let recruit_id = identities["recruit"].clone();
        assert!(fatality_filter_targets(&game).contains(&recruit_id));
        let kill = cast_fatality_filter_on(&mut game, &recruit_id);
        assert!(
            kill.iter()
                .any(|(event_type, _)| event_type == "minion-died")
        );
        assert!(!fatality_filter_alive(&game, &recruit_id));
        assert!(
            game.position.players[seat_index(Seat::South)]
                .cemetery
                .iter()
                .any(|card| card.instance_id == recruit_id)
        );
        assert!(fatality_filter_alive(&game, &identities["hidden"]));
    }

    pub fn rule_catalog_0723_rubble_at_nearby_location_is_valid_activate_sparkmage_target() {
        let manifest = selfplay_manifest_with(31, |manifest| {
            manifest["cards"]["north-avatar"]["tapDamageRandomOtherUnitAtNearbyLocationPerAirThresholdCastThisTurn"] =
                json!(true);
        });
        let mut game = Game::from_manifest_json(&manifest).expect("valid game");
        let c4 = Cell::parse("C4").expect("C4");
        game.position.rubble[c4.index()] = Some(
            identity_hash(&json!({ "fixture": "sparkmage-rubble" })).expect("Rubble identity"),
        );
        let north = &mut game.position.players[seat_index(Seat::North)];
        north.avatar.tapped = false;
        north.domain_established = true;
        let candidate_card = north.hand_spellbook.remove(0);
        game.position.units.push(UnitPosition {
            card: candidate_card,
            carried_lance_count: 0,
            controller: Seat::North,
            damage: 0,
            death_marked: false,
            disable_effects: Vec::new(),
            disabled_until_damaged: false,
            last_dropped_artifacts_turn: None,
            last_interacted_turn: None,
            last_picked_up_artifacts_turn: None,
            location: c4,
            occupied_cells: None,
            planar_gate_voidwalk: false,
            region: Region::Surface,
            stealthed: false,
            summoning_sickness: false,
            tapped: false,
            temporary_modifiers: TemporaryModifiers::new(),
            warded: false,
        });
        game.position.active_seat = Seat::North;
        game.position.decision_seat = Seat::North;
        game.position.phase = Phase::Main;

        let action = game
            .legal_actions()
            .expect("legal actions")
            .into_iter()
            .find(|action| {
                matches!(
                    action.descriptor,
                    ActionDescriptor::ActivateSparkmage {
                        target_location: Location {
                            cell,
                            region: Region::Surface,
                        },
                        ..
                    } if cell == c4
                )
            })
            .expect("Rubble is an existing surface target");
        let owned = game
            .clone()
            .apply_action_owned(&action)
            .expect("owned Sparkmage action");
        let mut speculative = game.clone();
        speculative
            .apply_action(&action)
            .expect("speculative Sparkmage action");
        let (outcomes, random_draws) = game
            .apply_action_recorded(&action)
            .expect("issued Sparkmage action");

        assert_eq!(
            outcomes
                .iter()
                .map(|(event_type, _)| event_type.as_str())
                .collect::<Vec<_>>(),
            ["sparkmage-activated"]
        );
        assert!(!random_draws.is_empty());
        assert_eq!(speculative.position, game.position);
        assert_eq!(owned.position, game.position);
        assert_eq!(
            owned.legal_actions().expect("owned next actions"),
            game.legal_actions().expect("recorded next actions")
        );
        assert!(game.position.players[seat_index(Seat::North)].avatar.tapped);
    }

    pub fn rule_catalog_0728_end_turn_cleanup_resets_both_players_air_threshold_counts() {
        let manifest = selfplay_manifest_with(31, |_| {});
        let mut game = Game::from_manifest_json(&manifest).expect("valid game");
        game.position.players[seat_index(Seat::North)].air_thresholds_cast_this_turn = Some(3);
        game.position.players[seat_index(Seat::South)].air_thresholds_cast_this_turn = Some(2);
        let mut events = Vec::new();
        let mut outcomes = OutcomeLog::Record(&mut events);
        game.finish_end_turn_cleanup(Seat::North, &mut outcomes)
            .expect("end-turn cleanup");
        assert_eq!(
            game.position.players[seat_index(Seat::North)].air_thresholds_cast_this_turn,
            Some(0)
        );
        assert_eq!(
            game.position.players[seat_index(Seat::South)].air_thresholds_cast_this_turn,
            Some(0)
        );
    }

    pub fn rule_catalog_0731_post_action_terminal_event_should_follow_magic_completion() {
        let mut events = vec![
            ("magic-cast".to_owned(), Value::Null),
            ("magic-resolved".to_owned(), Value::Null),
        ];
        let mut outcomes = OutcomeLog::Record(&mut events);
        let settlement_start = outcomes.len();
        outcomes.push("minion-died", || Value::Null);
        outcomes.push("game-ended", || Value::Null);
        outcomes.move_tail_before_completion(settlement_start);

        assert_eq!(
            events
                .iter()
                .map(|(event_type, _)| event_type.as_str())
                .collect::<Vec<_>>(),
            ["magic-cast", "minion-died", "magic-resolved", "game-ended",]
        );
    }

    #[expect(
        clippy::too_many_lines,
        reason = "one direct payment proof keeps self-play admission and zero/one-card legality together"
    )]
    pub fn rule_catalog_0729_alternate_summon_payments_should_be_admitted_and_require_their_costs()
    {
        let discard_manifest = selfplay_manifest_with(417, |manifest| {
            for ordinal in 1..=50 {
                manifest["cards"][format!("north-spell-{ordinal}")]["discardRandomCardInsteadOfMana"] =
                    json!(true);
            }
        });
        Game::from_manifest_json(&discard_manifest)
            .expect("valid random-discard manifest")
            .ensure_selfplay_supported()
            .expect("random-discard payment is self-play safe");

        let sacrifice_manifest = selfplay_manifest_with(417, |manifest| {
            manifest["cards"]["north-spell-1"]["sacrificeMinionAtSummoningLocationForManaDiscount"] =
                json!(2);
        });
        Game::from_manifest_json(&sacrifice_manifest)
            .expect("valid sacrifice-payment manifest")
            .ensure_selfplay_supported()
            .expect("sacrifice-discount payment is self-play safe");

        let mut game = Game::from_manifest_json(&discard_manifest).expect("valid Aramos game");
        let cell = Cell::parse("C4").expect("C4");
        let north = &mut game.position.players[seat_index(Seat::North)];
        let site_card = north.hand_atlas.remove(0);
        north.atlas.extend(std::mem::take(&mut north.hand_atlas));
        let aramos = north.hand_spellbook.remove(0);
        north
            .spellbook
            .extend(std::mem::take(&mut north.hand_spellbook));
        let aramos_instance_id = aramos.instance_id.clone();
        north.hand_spellbook.push(aramos);
        north.avatar.location = cell;
        north.domain_established = true;
        north.mana = 0;
        game.position.sites[cell.index()] = Some(SitePosition {
            card: site_card,
            controller: Seat::North,
            last_flight_turn: None,
            warded: false,
        });
        game.position.active_seat = Seat::North;
        game.position.decision_seat = Seat::North;
        game.position.phase = Phase::Main;

        assert!(
            !game
                .legal_actions()
                .expect("actions without a payment card")
                .iter()
                .any(|action| matches!(
                    action.descriptor,
                    ActionDescriptor::SummonMinion {
                        payment_mode: Some(SummonPaymentMode::RandomCardDiscard),
                        ..
                    }
                ))
        );

        let only_payment_card = game.position.players[seat_index(Seat::North)]
            .atlas
            .pop()
            .expect("one Atlas payment card");
        let payment_instance_id = only_payment_card.instance_id.clone();
        game.position.players[seat_index(Seat::North)]
            .hand_atlas
            .push(only_payment_card);
        game.position.players[seat_index(Seat::North)].mana = 1;
        let payment_actions = game.legal_actions().expect("actions with one payment card");
        assert!(payment_actions.iter().any(|action| matches!(
            action.descriptor,
            ActionDescriptor::SummonMinion {
                mana_cost: 1,
                payment_mode: None,
                ..
            }
        )));
        let action = payment_actions
            .into_iter()
            .find(|action| {
                matches!(
                    &action.descriptor,
                    ActionDescriptor::SummonMinion {
                        card_instance_id,
                        payment_mode: Some(SummonPaymentMode::RandomCardDiscard),
                        ..
                    } if *card_instance_id == aramos_instance_id
                )
            })
            .expect("random-discard summon");
        let (outcomes, random_draws) = game
            .apply_action_recorded(&action)
            .expect("issued random-discard summon");

        assert_eq!(random_draws.len(), 1);
        assert_eq!(random_draws[0].domain.exclusive_maximum, 1);
        assert_eq!(random_draws[0].domain.kind, "card_index_candidate");
        assert_eq!(random_draws[0].purpose, "summon_random_card_discard_cost");
        assert_eq!(
            outcomes
                .iter()
                .map(|(event_type, _)| event_type.as_str())
                .collect::<Vec<_>>(),
            ["card-discarded", "minion-summoned"]
        );
        assert_eq!(outcomes[0].1["instanceId"], payment_instance_id.as_str());
        assert_eq!(outcomes[0].1["zone"], "atlas");
        assert!(
            game.position.players[seat_index(Seat::North)]
                .cemetery
                .iter()
                .any(|card| card.instance_id == payment_instance_id)
        );
        assert_eq!(game.position.players[seat_index(Seat::North)].mana, 1);
    }

    fn burrow_target_bury_manifest(extra: &[(&str, Value)]) -> String {
        let extra = extra.to_vec();
        selfplay_manifest_with(31, move |manifest| {
            for ordinal in 1..=50 {
                manifest["cards"][format!("north-spell-{ordinal}")] = json!({
                    "burrowTargetMinionOrArtifact": true,
                    "cardType": "magic",
                    "manaCost": 0,
                    "thresholds": { "air": 0, "earth": 0, "fire": 0, "water": 0 },
                });
            }
            for (field, value) in &extra {
                manifest["cards"]["south-spell-1"][*field] = value.clone();
            }
        })
    }

    fn assert_burrow_target_manifest_admits(extra: &[(&str, Value)], label: &str) {
        Game::from_manifest_json(&burrow_target_bury_manifest(extra))
            .unwrap_or_else(|_| panic!("valid {label} manifest"))
            .ensure_selfplay_supported()
            .unwrap_or_else(|_| panic!("{label} is self-play safe"));
    }

